function draw(input) {
  const {board,width,height,params}=input;
  const beta=params.beta, n=params.zeros;
  const adam=Math.pow(beta,n), yogi=1;
  const blue='#307f99', orange='#ad512e', ink='#12394c', faint='#d9e3e6';
  board.line('legend-adam',18,22,40,22,blue,2.5);
  board.text('legend-adam-label','Adam',46,27,{color:ink,size:15});
  board.line('legend-yogi',126,22,148,22,orange,2.5);
  board.text('legend-yogi-label','Yogi',154,27,{color:ink,size:15});
  board.text('retained-title','历史二次矩保留比例',18,58,{color:ink,size:15});
  const f=board.axes('retention-axes',{xDomain:[0,30],yDomain:[0,1.1],xLabel:'连续零梯度次数 n',yLabel:'',box:[54,80,width-24,height-67],grid:true});
  const pts=Array.from({length:121},(_,i)=>[i/4,Math.pow(beta,i/4)]);
  board.curve('adam-retention',f,pts,{color:blue,width:2.5});
  board.curve('yogi-retention',f,[[0,1],[30,1]],{color:orange,width:2.5});
  board.line('selected-n',f.x(n),f.y(0),f.x(n),f.y(1),faint,1.5);
  board.circle('adam-dot',f.x(n),f.y(adam),5,blue);
  board.circle('yogi-dot',f.x(n),f.y(yogi),5,orange);
  board.text('selected-readout','n='+n+'：Adam '+(adam*100).toFixed(1)+'% · Yogi 100%',18,height-14,{size:15,color:ink});
  return {beta,n,initialSquareMoment:1-beta,adamSquareMoment:(1-beta)*adam,yogiSquareMoment:1-beta,adamRetention:adam,yogiRetention:yogi,gradientSequence:[1,...Array(n).fill(0)],convention:'两者从s0=0开始，先接受g=1，然后连续n次g=0；展示未校正s/s1。曲线连接整数更新，非连续时间优化。'};
}
